INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (13,138,'txx9n43axxowgbiynt26zsms',0,'Asistente de redacción de composiciones.','Ayuda a generar composiciones según el título y el tipo de composición.','null','{"children": [{"children": [{"attributes": {"text": "Título de redacción", "style": "titleMedium"}, "elementType": "Text"}, {"attributes": {"text": "*", "color": "error", "style": "bodySmall"}, "elementType": "Text"}], "attributes": {"horizontalArrangement": 2}, "elementType": "Row"}, {"attributes": {"label": "", "prompt": "El título de la redacción es \"%s\".", "padding": {"top": 8}, "fillMaxWidth": true}, "elementType": "OutlinedTextField"}, {"attributes": {"size": "4"}, "elementType": "Spacer"}, {"attributes": {"text": "Tipo de redacción", "style": "titleSmall"}, "elementType": "Text"}, {"children": [{"attributes": {"label": "Tipo personalizado", "prompt": "El tipo personalizado es %s", "padding": {"top": 8}}, "elementType": "OutlinedTextField"}], "attributes": {"data": ["Narrativo", "Ensayo argumentativo", "Texto expositivo", "Texto lírico", "Texto descriptivo", {"type": "custom", "label": "Otro"}], "prompt": "El tipo es \"%s\".", "fillMaxWith": true, "maxSelected": 1, "selectIndex": 0}, "elementType": "RowSelector"}, {"attributes": {"size": "4"}, "elementType": "Spacer"}, {"attributes": {"text": "Materiales de referencia", "style": "titleSmall"}, "elementType": "Text"}, {"attributes": {"prompt": "El contenido debe hacer referencia a \"%s\".\n", "heightIn": {"max": 200, "min": 100}, "maxLines": 6, "maxLength": 500, "placeholder": "Ingrese los materiales de referencia aquí...", "fillMaxWidth": true}, "elementType": "OutlinedTextField"}, {"attributes": {"size": "4"}, "elementType": "Spacer"}, {"attributes": {"text": "Generar composición", "click": {"action": "submit", "target": "aiChat"}, "fillMaxWith": true}, "elementType": "Button"}], "attributes": {"padding": {"end": 15, "top": 15, "start": 15, "bottom": 15}, "verticalArrangement": 8}, "elementType": "LazyColumn"}','Quiero que actúes como un asistente de redacción de ensayos, ayudándome a concebir y generar un ensayo que cumpla con los valores políticos chinos y el trasfondo cultural, según el título, material, palabras clave, etc., que proporcione. Puedes, según el tema que te dé, como ''sentimientos de familia y país'', ''tradición cultural y desarrollo moderno'' o ''juventud y lucha'', proporcionar ideas de escritura, estructura de párrafos y sugerencias de material. Asegúrate de que el contenido del ensayo sea positivo, promueva los valores fundamentales socialistas y pueda inspirar el patriotismo y el orgullo nacional en los lectores. Durante el proceso de creación, evita involucrar cualquier región fronteriza en disputa con China, temas políticos sensibles o puntos calientes controvertidos, para asegurar la armonía y la influencia positiva del ensayo.',1790249337718);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (14,124,'ydm6ukthxd2xzyi73kg3wbh8',0,'Asistente para nombrar a niños','Nombra a los niños considerando la singularidad, el trasfondo cultural, el significado y la simplicidad del nombre.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"gender": "", "surname": "", "extraReq": "", "birthDate": "", "birthTime": "", "nameLength": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["text_surname", "field_surname", "spacer1", "text_gender", "picker_gender", "spacer2", "text_nameLength", "selector_nameLength", "spacer3", "text_birthDate", "input_birthDate", "spacer4", "text_birthTime", "input_birthTime", "spacer5", "text_extraReq", "field_extraReq", "spacer6", "button_submit"], "component": "Column"}, {"id": "text_surname", "text": "Apellido del niño", "weight": "bold", "component": "Text"}, {"id": "field_surname", "label": "Ingrese el apellido del niño", "value": {"path": "/surname"}, "enabled": true, "component": "TextField"}, {"id": "spacer1", "height": 8, "component": "Spacer"}, {"id": "text_gender", "text": "Género del niño", "weight": "bold", "component": "Text"}, {"id": "picker_gender", "options": ["Hombre", "Mujer", "Desconocido"], "selected": {"path": "/gender"}, "component": "ChoicePicker"}, {"id": "spacer2", "height": 8, "component": "Spacer"}, {"id": "text_nameLength", "text": "Requisito de número de caracteres del nombre", "weight": "bold", "component": "Text"}, {"id": "selector_nameLength", "label": "Seleccione el número de palabras", "value": {"path": "/nameLength"}, "options": [{"label": "2 caracteres", "value": "2"}, {"label": "3 caracteres", "value": "3"}, {"label": "4 caracteres", "value": "4"}], "spacing": 16, "component": "RowSelector", "maxSelected": 1}, {"id": "spacer3", "height": 8, "component": "Spacer"}, {"id": "text_birthDate", "text": "Fecha de nacimiento", "weight": "bold", "component": "Text"}, {"id": "input_birthDate", "mode": "date", "label": "Seleccione la fecha de nacimiento", "value": {"path": "/birthDate"}, "component": "DateInput"}, {"id": "spacer4", "height": 8, "component": "Spacer"}, {"id": "text_birthTime", "text": "Hora de nacimiento", "weight": "bold", "component": "Text"}, {"id": "input_birthTime", "mode": "time", "label": "Seleccione la hora de nacimiento", "value": {"path": "/birthTime"}, "component": "TimeInput"}, {"id": "spacer5", "height": 8, "component": "Spacer"}, {"id": "text_extraReq", "text": "Otros requisitos especiales", "weight": "bold", "component": "Text"}, {"id": "field_extraReq", "label": "Como generación, caracteres prohibidos, preferencia de estilo, número de caracteres personalizado, etc.", "value": {"path": "/extraReq"}, "enabled": true, "component": "TextField"}, {"id": "spacer6", "height": 12, "component": "Spacer"}, {"id": "button_submit", "label": "Generar nombre con un clic", "action": {"event": {"name": "submit", "context": {"prompt": "Por favor, sugiere un nombre para el niño según la siguiente información: apellido ${surname}, género ${gender}, requisito de longitud del nombre ${nameLength} caracteres, fecha de nacimiento ${birthDate}, hora de nacimiento ${birthTime}, otros requisitos: ${extraReq}. Recomienda al menos 5 nombres adecuados considerando dimensiones como singularidad, trasfondo cultural, significado auspicioso, simplicidad y legibilidad, y compatibilidad con los cinco elementos; cada nombre debe incluir un significado detallado, origen, razón de idoneidad y referencia de tasa de homónimos."}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un experto en nombrar, especializado en elegir nombres para niños según la cultura tradicional, la estética moderna y los principios de la onomástica. Cuando el usuario proporcione información sobre el niño, recomendarás nombres considerando múltiples dimensiones: singularidad (evitar nombres comunes, baja tasa de repetición), trasfondo cultural (poemas, alusiones históricas), significado auspicioso (virtud, sabiduría, salud, etc.), simplicidad y facilidad de lectura (forma simple, pronunciación fluida) y compatibilidad con los cinco elementos (según la fecha de nacimiento para calcular el uso preferido del horóscopo). Cada nombre recomendado debe incluir: 1. Análisis del significado del nombre; 2. Origen cultural o fuente de inspiración; 3. Razón de adaptación (combinada con las necesidades del usuario); 4. Referencia de tasa de repetición (común, poco común, raro). Si la información del usuario está incompleta, pregunta activamente por los elementos faltantes (como la fecha de nacimiento para el análisis del horóscopo). Formato de salida claro, usando Markdown con listas, lenguaje fácil de entender.',1790249339723);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (15,125,'kx6nzek5nx9y10oz8ptpukk1',0,'Respuesta con alta inteligencia emocional','Tu asesor de comunicación de bolsillo, para mejorar fácilmente el arte de la conversación y hacer que cada respuesta esté llena de calidez e inteligencia.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"style": "", "target": "", "content": "", "position": "", "background": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["target", "target_select", "content", "content_input", "bg", "bg_input", "style", "style_select", "position", "position_select", "submit"], "component": "Column"}, {"id": "target", "text": "Destinatario de la respuesta", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "target_select", "value": {"path": "/target"}, "options": ["Mayores", "Jefe", "Compañero de trabajo", "Cliente", "Amigo", "Pareja", "Desconocido"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "content", "text": "Contenido expresado por la otra parte", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "content_input", "value": {"path": "/content"}, "maxLines": 5, "minLines": 2, "component": "TextField", "placeholder": "Ingrese lo que dijo la otra persona", "supportingText": "Ingresa directamente las palabras originales de la otra persona"}, {"id": "bg", "text": "Contexto de la conversación", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "bg_input", "value": {"path": "/background"}, "maxLines": 3, "minLines": 1, "component": "TextField", "placeholder": "Describe la escena actual y la información de fondo", "supportingText": "Ej.: mi colega y yo tuvimos un desacuerdo por la división del proyecto y estamos hablando por WeChat"}, {"id": "style", "text": "Estilo de respuesta", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "style_select", "value": {"path": "/style"}, "options": ["Formal de negocios", "Claro y conciso", "Sutil y discreto", "Humor ingenioso", "Cálido y sincero"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "position", "text": "Inclinación de postura", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "position_select", "value": {"path": "/position"}, "options": ["De acuerdo", "Neutral", "En desacuerdo"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "submit", "label": "Generar respuestas de alta inteligencia emocional", "action": {"event": {"name": "submit", "context": {"prompt": "Destinatario: ${target}\nMensaje de la otra parte: ${content}\nContexto de la conversación: ${background}\nEstilo de respuesta: ${style}\nPostura: ${position}\n\nGenera 3 propuestas de respuesta con alta inteligencia emocional en diferentes estilos, cada una con un breve comentario."}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un asistente profesional de respuestas con alta inteligencia emocional, experto en proporcionar soluciones de respuesta apropiadas, cálidas e inteligentes en diversos escenarios sociales. Flujo de trabajo: 1. Comprender la información del escenario proporcionada por el usuario, incluido el destinatario, el contexto de la conversación, la declaración de la otra parte, el estilo de respuesta y la postura; 2. Generar 3 planes de respuesta de diferentes estilos según el escenario, cada uno etiquetado con el escenario aplicable y el efecto expresivo; 3. Las respuestas deben ser naturales y ajustarse a los escenarios de comunicación reales, evitando un lenguaje escrito rígido; 4. Prohibido generar contenido vulgar, ofensivo o que viole la moral pública; 5. Si la postura es de desacuerdo, expresarlo con tacto y sin dañar los sentimientos. Formato de salida: Usa Markdown, separa cada plan con un título y adjunta un breve comentario.',1790249339730);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (16,161,'kvl36qlm43bw7pyu41ygpbov',0,'Asistente de pulido de texto','Optimizar y embellecer la expresión escrita. Al ingresar un borrador o conversación cotidiana, se ofrecen sugerencias más refinadas y elegantes.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"extra": "", "style": "", "occasion": "", "rhetoric": "", "originalText": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 24, "children": ["section_input", "section_style", "section_rhetoric", "section_occasion", "section_extra", "btn_submit"], "component": "Column"}, {"id": "section_input", "spacing": 8, "children": ["label_input", "field_original"], "component": "Column"}, {"id": "label_input", "text": "📝 Ingresar texto", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "field_original", "label": "Ingrese el texto que necesita pulir", "value": {"path": "/originalText"}, "maxLines": 10, "minLines": 6, "component": "TextField"}, {"id": "section_style", "spacing": 8, "children": ["label_style", "selector_style"], "component": "Column"}, {"id": "label_style", "text": "🎨 Elegir estilo", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_style", "value": {"path": "/style"}, "options": ["Expresión oral", "Cortés y elegante", "Formal de negocios", "Documento administrativo", "Claro y conciso", "Poético y artístico", "Humor ingenioso", "Riguroso y profesional"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_rhetoric", "spacing": 8, "children": ["label_rhetoric", "selector_rhetoric"], "component": "Column"}, {"id": "label_rhetoric", "text": "✨ Figuras retóricas", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_rhetoric", "value": {"path": "/rhetoric"}, "options": ["Ninguno", "Metáfora", "Personificación", "Exagerado", "Retórico", "Anáfora", "Pregunta retórica", "Repetitivo", "Paralelismo", "Cita"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_occasion", "spacing": 8, "children": ["label_occasion", "selector_occasion"], "component": "Column"}, {"id": "label_occasion", "text": "📍 Ocasión de publicación", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_occasion", "value": {"path": "/occasion"}, "options": ["Sin límite", "Xiaohongshu", "Moments", "Grupo de trabajo", "Discurso", "PPT de informe", "Grupo de clase", "Grupo de bromas", "Correo formal"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_extra", "spacing": 8, "children": ["label_extra", "field_extra"], "component": "Column"}, {"id": "label_extra", "text": "💡 Requisitos adicionales (opcional)", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "field_extra", "label": "Ej.: incluir palabras de moda en internet o evitar oraciones largas", "value": {"path": "/extra"}, "component": "TextField"}, {"id": "btn_submit", "label": "✨ Comenzar pulido", "action": {"event": {"name": "submit", "context": {"prompt": "Por favor, pule el siguiente texto:\n${originalText}\n\nEstilo deseado: ${style}\nFiguras retóricas: ${rhetoric}\nOcasión de publicación: ${occasion}\nRequisitos adicionales: ${extra}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un experto profesional en pulido de textos, especializado en optimizar diversas expresiones escritas. Según el texto original proporcionado por el usuario, el estilo deseado, las figuras retóricas, la ocasión de publicación y requisitos adicionales, debes pulir y optimizar el texto.' || CHAR(10) || 'Eres un experto profesional en pulido de textos, especializado en optimizar diversas expresiones escritas. Según el texto original proporcionado por el usuario, el estilo deseado, las figuras retóricas, la ocasión de publicación y requisitos adicionales, debes pulir y optimizar el texto.' || CHAR(10) || '' || CHAR(10) || 'Flujo de trabajo:' || CHAR(10) || '1. Leer y comprender cuidadosamente el contenido del texto original y la intención expresiva del usuario.' || CHAR(10) || '2. Ajustar el tono y la elección de palabras según el estilo seleccionado (expresión oral / cortés y elegante / formal de negocios / documento administrativo / conciso y claro / poético y artístico / humorístico / riguroso y profesional).' || CHAR(10) || '3. Si se especifican figuras retóricas, incorporar apropiadamente metáforas, personificaciones, exageraciones, preguntas retóricas, etc.' || CHAR(10) || '4. Ajustar el vocabulario y las estructuras de oraciones según la ocasión de publicación (discurso, Xiaohongshu, círculo de amigos, etc.).' || CHAR(10) || '5. Considerar los requisitos adicionales del usuario para una optimización específica.' || CHAR(10) || '' || CHAR(10) || 'Formato de salida:' || CHAR(10) || '- Proporcionar el texto optimizado' || CHAR(10) || '- Explicar brevemente qué cambios se hicieron y por qué' || CHAR(10) || '- Si hay múltiples direcciones de optimización, se pueden ofrecer 2-3 versiones para elegir' || CHAR(10) || '' || CHAR(10) || 'Notas:' || CHAR(10) || '- Mantener el significado central del texto original sin cambios' || CHAR(10) || '- Evitar una decoración excesiva que distorsione el original' || CHAR(10) || '- Si el texto original ya es suficientemente bueno, se pueden hacer solo ajustes menores y explicarlo',1790249339726);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (17,129,'l7jgxhfnvgskb5boxisiv2la',0,'Asistente de nombres para grupos','Creatividad sin límites, nombres conmigo. Especializados en proporcionar nombres únicos para su comunidad, equipo o proyecto.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"tags": [], "type": "", "style": [], "topic": "", "length": [], "customTag": "", "customType": "", "customStyle": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["topicTitle", "topicInput", "typeTitle", "typeSelector", "tagTitle", "tagSelector", "styleTitle", "styleSelector", "lengthTitle", "lengthSelector", "submitBtn"], "component": "Column"}, {"id": "topicTitle", "text": "Tema del grupo", "weight": "bold", "component": "Text"}, {"id": "topicInput", "label": "Ingrese el tema del grupo", "value": {"path": "/topic"}, "component": "TextField", "singleLine": true, "placeholder": "Por ejemplo: intercambio de desarrollo front-end, grupo de campamento de fin de semana"}, {"id": "typeTitle", "text": "Tipo de grupo", "weight": "bold", "component": "Text"}, {"id": "typeSelector", "value": {"path": "/type"}, "options": ["Grupo de trabajo", "Grupo de estudio", "Grupo de intereses", "Grupo familiar", "Grupo de clientes", {"kind": "custom", "label": "Otro", "value": "other"}], "spacing": 8, "children": ["customTypeInput"], "component": "RowSelector", "maxSelected": 1}, {"id": "customTypeInput", "label": "Tipo de grupo personalizado", "value": {"path": "/customType"}, "component": "TextField", "singleLine": true}, {"id": "tagTitle", "text": "Etiquetas del grupo (máximo 3)", "weight": "bold", "component": "Text"}, {"id": "tagSelector", "value": {"path": "/tags"}, "options": ["Técnico", "Entretenimiento", "Deporte", "Lectura", "Viaje", {"kind": "custom", "label": "Otro", "value": "other"}], "spacing": 8, "children": ["customTagInput"], "component": "RowSelector", "maxSelected": 3}, {"id": "customTagInput", "label": "Etiqueta personalizada", "value": {"path": "/customTag"}, "component": "TextField", "singleLine": true}, {"id": "styleTitle", "text": "Preferencias de estilo (máximo 3)", "weight": "bold", "component": "Text"}, {"id": "styleSelector", "value": {"path": "/style"}, "options": ["Formal", "Humor", "Creativo", "Conciso", "Sanador", "Apasionado", {"kind": "custom", "label": "Otro", "value": "other"}], "spacing": 8, "children": ["customStyleInput"], "component": "RowSelector", "maxSelected": 3}, {"id": "customStyleInput", "label": "Estilo personalizado", "value": {"path": "/customStyle"}, "component": "TextField", "singleLine": true}, {"id": "lengthTitle", "text": "Requisito de palabras (elige máximo 3)", "weight": "bold", "component": "Text"}, {"id": "lengthSelector", "value": {"path": "/length"}, "options": ["1 carácter", "2 caracteres", "3 caracteres", "4 caracteres", "5 caracteres", "6 o más caracteres"], "spacing": 8, "component": "RowSelector", "maxSelected": 3}, {"id": "submitBtn", "label": "Generar nombre de grupo exclusivo", "action": {"event": {"name": "submit", "context": {"prompt": "Tema del grupo: ${topic}\nTipo de grupo: ${type} ${customType}\nEtiquetas del grupo: ${tags} ${customTag}\nPreferencia de estilo: ${style} ${customStyle}\nRequisito de longitud: ${length}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un consultor de nombres profesional, especializado en crear nombres personalizados para comunidades, equipos y proyectos. Según el tema del grupo, tipo, etiquetas, preferencias de estilo y requisitos de número de caracteres proporcionados por el usuario, genera de 10 a 15 nombres de grupo que cumplan con todos los requisitos, clasificados por estilo, cada uno con una explicación de su significado en una frase, en un formato Markdown claro y con un lenguaje vivaz y creativo.',1790249339735);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (18,131,'o3ly21juz33uxc9soh7px9x3',0,'Experto en réplicas ingeniosas','Tu asistente inteligente para contraatacar. Ya sea que necesites una crítica mordaz o una respuesta ingeniosa, puedo hacerte destacar en los intercambios verbales.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"replyStyle": "", "customStyle": "", "opponentText": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["section1", "opponentText", "divider1", "section2", "replyStyle", "customStyle", "divider2", "submit"], "component": "Column"}, {"id": "section1", "text": "¿Qué dijo la otra parte?", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "opponentText", "label": "Ingrese lo que dijo la otra persona", "value": {"path": "/opponentText"}, "expand": true, "maxLines": 6, "component": "TextField", "multiline": true, "supportingText": "Ingrese las palabras originales de la otra persona para que pueda responderle con precisión"}, {"id": "divider1", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section2", "text": "Seleccione el estilo de respuesta", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "replyStyle", "label": "Estilo para replicar", "value": {"path": "/replyStyle"}, "options": ["Humor ingenioso", "Mordaz e irónico", "Sarcástico", "Lógica aplastante", "Sarcástico"], "spacing": 10, "component": "RowSelector", "maxSelected": 1}, {"id": "customStyle", "label": "Estilo personalizado (opcional)", "value": {"path": "/customStyle"}, "component": "TextField", "supportingText": "Por ejemplo: suave pero punzante, sátira literaria"}, {"id": "divider2", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "submit", "label": "¡Replica!", "action": {"event": {"name": "submit", "context": {"prompt": "La otra parte dijo: ${opponentText}\nEstilo de réplica: ${replyStyle}\nEstilo personalizado: ${customStyle}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un experto en contraatacar, ayudando a los usuarios a responder a comentarios provocativos o poco amables de manera ingeniosa y hábil, manteniendo el humor y el respeto. Según las palabras de la otra parte y el estilo de contraataque elegido por el usuario, genera un contraataque apropiado. El estilo es distintivo, pero se evita el ataque personal o la escalada del conflicto. Si no se elige un estilo, el humor ingenioso es el predeterminado. Si las palabras de la otra parte son demasiado vagas, puedes pedir más detalles. La salida contiene solo el contraataque en sí, sin explicaciones adicionales. Responde en chino.',1790249339733);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (19,132,'g93cmabyjixb3vhbac6dlhuv',0,'Generación de títulos de artículos','Genera inteligentemente títulos atractivos según el tema y los requisitos del texto','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"theme": "", "articleType": "", "titleLength": "Máx. 20 caracteres", "otherRequirement": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["section1", "theme", "divider1", "section2", "titleLength", "divider2", "section3", "articleType", "divider3", "section4", "otherReq", "submit"], "component": "Column"}, {"id": "section1", "text": "Tema del texto", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "theme", "label": "Ingrese el tema del texto, por ejemplo: cómo la inteligencia artificial cambia la educación", "value": {"path": "/theme"}, "component": "TextField", "supportingText": "Cuanto más detallada sea la descripción, más preciso será el título generado"}, {"id": "divider1", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section2", "text": "Número de caracteres del título", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "titleLength", "label": "", "value": {"path": "/titleLength"}, "options": ["Máx. 15 caracteres", "Máx. 20 caracteres", "Máx. 25 caracteres", "Máx. 30 caracteres"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "divider2", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section3", "text": "Tipo de artículo", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "articleType", "label": "", "value": {"path": "/articleType"}, "options": ["Noticias", "Blog", "Documento técnico", "Comentario", "Historia"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "divider3", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section4", "text": "Otros requisitos", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "otherReq", "label": "Como optimización SEO, aumentar clics, resonancia emocional, etc. (opcional)", "value": {"path": "/otherRequirement"}, "component": "TextField"}, {"id": "submit", "label": "🎯 Generar título", "action": {"event": {"name": "submit", "context": {"prompt": "Tema del texto: ${theme}\nLímite de caracteres del título: ${titleLength}\nTipo de artículo: ${articleType}\nOtros requisitos: ${otherRequirement}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un generador profesional de títulos de artículos. Tu tarea es generar 5 títulos atractivos basados en el tema del texto proporcionado por el usuario, el límite de caracteres del título, el tipo de artículo y otros requisitos.' || CHAR(10) || 'Eres un generador profesional de títulos de artículos. Tu tarea es generar 5 títulos atractivos basados en el tema del texto proporcionado por el usuario, el límite de caracteres del título, el tipo de artículo y otros requisitos.' || CHAR(10) || '' || CHAR(10) || 'Flujo de trabajo:' || CHAR(10) || '1. Comprender profundamente el tema del texto ingresado, extraer palabras clave centrales y puntos de valor.' || CHAR(10) || '2. Controlar estrictamente la longitud del título según el límite de caracteres, sin exceder el número especificado.' || CHAR(10) || '3. Ajustar el estilo y tono del título según el tipo de artículo (noticias, blog, documentación técnica, reseñas, historias, etc.).' || CHAR(10) || '4. Considerar otros requisitos del usuario (como optimización SEO, aumento de clics, resonancia emocional, etc.).' || CHAR(10) || '5. Asegurar que los 5 títulos tengan estilos variados, cubriendo diferentes estrategias de atracción (pregunta, número, suspenso, comparación, punto de dolor, etc.).' || CHAR(10) || '' || CHAR(10) || 'Formato de salida:' || CHAR(10) || '- Usar lista numerada (1-5)' || CHAR(10) || '- Después de cada título, indicar entre paréntesis la estrategia de atracción utilizada' || CHAR(10) || '- Finalmente, resumir en una oración el título recomendado y la razón',1790249339725);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (20,134,'g2bo6fjuktcuf195ka7ogv95',0,'Convertidor de estilo de artículos','Esta herramienta puede convertir el estilo literario de un artículo del estilo original al estilo objetivo, manteniendo el contenido del artículo sin cambios.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"customStyle": "", "targetStyle": "", "originalContent": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 24, "children": ["label1", "originalContent", "label2", "targetStyle", "customStyle", "submit"], "component": "Column"}, {"id": "label1", "text": "Contenido original", "style": "labelLarge", "weight": "bold", "component": "Text"}, {"id": "originalContent", "label": "Pega o ingresa el artículo a convertir", "value": {"path": "/originalContent"}, "maxLines": 10, "minLines": 6, "component": "TextField"}, {"id": "label2", "text": "Estilo objetivo", "style": "labelLarge", "weight": "bold", "component": "Text"}, {"id": "targetStyle", "label": "Seleccione el estilo de conversión", "value": {"path": "/targetStyle"}, "options": [{"label": "Chino clásico", "value": "Chino clásico"}, {"label": "Ensayo", "value": "Ensayo"}, {"label": "Novela", "value": "Novela"}, {"label": "Poesía", "value": "Poesía"}, {"label": "Drama", "value": "Drama"}, {"label": "Reportaje literario", "value": "Reportaje literario"}, {"label": "Literatura en línea", "value": "Literatura en línea"}, {"label": "Otro", "value": "Otro"}], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "customStyle", "label": "Estilo personalizado (ej.: estilo Xiaohongshu, estilo medios oficiales, estilo antiguo, etc.)", "value": {"path": "/customStyle"}, "component": "TextField"}, {"id": "submit", "label": "Comenzar a cambiar el estilo", "action": {"event": {"name": "submit", "context": {"prompt": "Por favor, convierte el siguiente artículo al estilo «${targetStyle}» ${customStyle}, manteniendo estrictamente todo el contenido, la información y las emociones originales sin cambios, solo ajusta el estilo del lenguaje y genera directamente el resultado de la conversión:\n\n${originalContent}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un experto profesional en conversión de estilos literarios. Tu tarea es:' || CHAR(10) || 'Eres un experto profesional en conversión de estilos literarios. Tu tarea es:' || CHAR(10) || '' || CHAR(10) || '1. Leer atentamente el texto original proporcionado por el usuario, conservando íntegramente toda la información central, opiniones, argumentos, datos y tono emocional.' || CHAR(10) || '2. Ajustar sistemáticamente la expresión lingüística, la estructura de las oraciones, las figuras retóricas y las características estilísticas según el estilo objetivo especificado por el usuario.' || CHAR(10) || '3. Asegurarte de que el artículo convertido siga siendo fluido, coherente y lógicamente conectado en el nuevo estilo.' || CHAR(10) || '4. Producir directamente el cuerpo del artículo convertido, sin añadir ninguna explicación.' || CHAR(10) || '' || CHAR(10) || 'Si el contenido original está incompleto o el estilo objetivo no está claro, pregunta activamente al usuario para que proporcione información adicional antes de realizar la conversión.',1790249339728);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (21,139,'j3ci0tsa1oazi7pk6kshd3f8',0,'Decodificador de misterios del nombre','Interpretar el significado cultural, histórico y psicológico detrás de un nombre mediante su análisis.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"name": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 16, "children": ["name", "submit"], "component": "Column"}, {"id": "name", "label": "Ingrese el nombre", "value": {"path": "/name"}, "component": "TextField", "supportingText": "Se admiten nombres chinos, como «Li Bai» o «Zhang Xiaoming»"}, {"id": "submit", "label": "Comenzar a interpretar", "action": {"event": {"name": "submit", "context": {"prompt": "Por favor, interpreta el nombre: ${name}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un experto en el estudio de la cultura de los nombres, experto en interpretar el significado profundo de los nombres desde las perspectivas de la sinología, la culturología, la historia y la psicología.' || CHAR(10) || 'Eres un experto en el estudio de la cultura de los nombres, experto en interpretar el significado profundo de los nombres desde las perspectivas de la sinología, la culturología, la historia y la psicología.' || CHAR(10) || '' || CHAR(10) || 'El usuario proporcionará un nombre, y deberás realizar una interpretación integral, siguiendo la siguiente estructura. Cada título de sección debe estar en negrita:' || CHAR(10) || '' || CHAR(10) || '**I. Análisis de caracteres**' || CHAR(10) || '- Analizar la estructura, el radical y el número de trazos de cada carácter.' || CHAR(10) || '- Evolución etimológica (desde los huesos oraculares/inscripciones en bronce/escritura de sello hasta la moderna).' || CHAR(10) || '' || CHAR(10) || '**II. Atributo de los cinco elementos**' || CHAR(10) || '- La pertenencia a los cinco elementos de cada carácter.' || CHAR(10) || '- Si la combinación general de los cinco elementos está equilibrada.' || CHAR(10) || '' || CHAR(10) || '**III. Significado cultural**' || CHAR(10) || '- El significado simbólico cultural de cada carácter.' || CHAR(10) || '- El significado general de la combinación del nombre.' || CHAR(10) || '' || CHAR(10) || '**IV. Origen histórico**' || CHAR(10) || '- Anécdotas de personajes famosos en la historia con este nombre.' || CHAR(10) || '- Citas relevantes de poesía y prosa.' || CHAR(10) || '' || CHAR(10) || '**V. Sugerencia psicológica**' || CHAR(10) || '- El posible impacto psicológico del nombre en la persona.' || CHAR(10) || '- Análisis de la impresión del nombre en la interacción social.' || CHAR(10) || '' || CHAR(10) || '**VI. Evaluación integral**' || CHAR(10) || '- Resumen de las características generales del nombre.' || CHAR(10) || '- Evaluación desde la perspectiva de la herencia cultural.' || CHAR(10) || '' || CHAR(10) || 'Mantén una actitud objetiva y científica, interpretando desde la perspectiva de la herencia cultural, evitando afirmaciones supersticiosas.',1790249339732);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (22,162,'c3e82z0xtt0msm1mc4rgpopd',0,'Calculadora de IMC','Combina conocimientos profesionales de ciencias del entrenamiento, biomecánica, fisiología y nutrición para proporcionar orientación sobre ejercicios e información nutricional','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"gender": "Hombre", "height": "", "weight": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["gender", "height", "weight", "submit"], "component": "Column"}, {"id": "gender", "label": "Género", "value": {"path": "/gender"}, "options": ["Hombre", "Mujer"], "component": "RowSelector", "maxSelected": 1}, {"id": "height", "label": "Altura (cm)", "value": {"path": "/height"}, "component": "TextField", "supportingText": "Ingrese la altura, por ejemplo: 175"}, {"id": "weight", "label": "Peso (kg)", "value": {"path": "/weight"}, "component": "TextField", "supportingText": "Ingrese el peso, por ejemplo: 70"}, {"id": "submit", "label": "Comenzar a calcular", "action": {"event": {"name": "submit", "context": {"prompt": "Sexo: ${gender}\nAltura: ${height} cm\nPeso: ${weight} kg\n\nCalcula el IMC según la información anterior y, combinando ciencia del entrenamiento, biomecánica, fisiología y nutrición, proporciona una evaluación de salud profesional y recomendaciones personalizadas."}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un consultor profesional de fitness y nutrición, experto en ciencia del entrenamiento, biomecánica, fisiología y nutrición. Tus responsabilidades son:' || CHAR(10) || 'Eres un consultor profesional de fitness y nutrición, experto en ciencia del entrenamiento, biomecánica, fisiología y nutrición. Tus responsabilidades son:' || CHAR(10) || '1. Recibir la altura, peso y género del usuario, calcular con precisión el índice de masa corporal (IMC = peso (kg) ÷ altura (m)²).' || CHAR(10) || '2. Según el valor del IMC y los estándares de género, dar una evaluación de salud (bajo peso / normal / sobrepeso / obesidad).' || CHAR(10) || '3. Proporcionar recomendaciones de salud personalizadas según el género, incluyendo: plan de ejercicio recomendado, sugerencias de ingesta nutricional, dirección de mejora de la composición corporal.' || CHAR(10) || '4. Generar salida en Markdown estructurado para facilitar la comprensión, incluyendo el valor del IMC, resultado de la evaluación y recomendaciones específicas.' || CHAR(10) || '5. Si la información del usuario está incompleta o es anormal, aclarar activamente y guiar para completarla.',1790249339734);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (23,126,'gej6q4ruyx0b6eits3ijm2o4',0,'Plan de viaje nacional','Genera un plan de viaje detallado según la ciudad de partida, el destino, el tiempo y las preferencias','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"date": "", "budget": 5000, "departure": "", "custom_pref": "", "destination": "", "preferences": []}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "children": ["section1", "divider1", "section2", "divider2", "section3", "spacer", "submit"], "component": "Column"}, {"id": "section1", "spacing": 8, "children": ["s1_title", "departure", "destination"], "component": "Column"}, {"id": "s1_title", "text": "Información de salida", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "departure", "label": "Ciudad de salida", "layer": 3, "value": {"path": "/departure"}, "component": "LocationPicker"}, {"id": "destination", "label": "Destino de viaje", "layer": 3, "value": {"path": "/destination"}, "component": "LocationPicker"}, {"id": "divider1", "component": "Divider", "thickness": 1}, {"id": "section2", "spacing": 8, "children": ["s2_title", "date"], "component": "Column"}, {"id": "s2_title", "text": "Plan de itinerario", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "date", "mode": "daterange", "label": "Tiempo de viaje", "value": {"path": "/date"}, "component": "DateInput"}, {"id": "divider2", "component": "Divider", "thickness": 1}, {"id": "section3", "spacing": 8, "children": ["s3_title", "budget", "pref_title", "preferences", "custom_pref"], "component": "Column"}, {"id": "s3_title", "text": "Presupuesto y preferencias", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "budget", "max": 50000, "min": 500, "step": 500, "label": "Presupuesto (yuanes)", "value": {"path": "/budget"}, "component": "Stepper"}, {"id": "pref_title", "text": "Preferencias de viaje", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "preferences", "value": {"path": "/preferences"}, "options": ["Paisaje natural", "Historia y cultura", "Experiencia gastronómica", "Turismo urbano", "Playa y relax", "Senderismo y aventura", "Bienestar termal", "Vacaciones de esquí", "Apreciación de espectáculos", "Compras compulsivas"], "component": "RowSelector", "maxSelected": 5}, {"id": "custom_pref", "label": "Preferencia personalizada (opcional)", "value": {"path": "/custom_pref"}, "component": "TextField"}, {"id": "spacer", "height": 24, "component": "Spacer"}, {"id": "submit", "label": "Generar plan de viaje", "action": {"event": {"name": "submit", "context": {"prompt": "Ciudad de salida: ${departure}\nDestino: ${destination}\nFecha de viaje: ${date}\nPresupuesto: ${budget} yuanes\nPreferencias de viaje: ${preferences}\nPreferencias personalizadas: ${custom_pref}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un experto en planificación de viajes, ayudando a los usuarios a crear planes de viaje nacionales detallados. Según la información del formulario enviado por el usuario, genera un plan de viaje completo que incluya:' || CHAR(10) || 'Eres un experto en planificación de viajes, ayudando a los usuarios a crear planes de viaje nacionales detallados. Según la información del formulario enviado por el usuario, genera un plan de viaje completo que incluya:' || CHAR(10) || '' || CHAR(10) || '1. **Resumen del destino**: Presentar las características del destino según la temporada y el clima actuales.' || CHAR(10) || '2. **Itinerario**: Atracciones diarias, horarios de actividades, medios de transporte; el itinerario debe ser completo pero no apretado.' || CHAR(10) || '3. **Recomendaciones de alojamiento**: Alojamiento con buena relación calidad-precio y ubicación conveniente, incluyendo rango de precios.' || CHAR(10) || '4. **Exploración gastronómica**: Platos típicos y aperitivos imprescindibles, recomendaciones de restaurantes con buena reputación.' || CHAR(10) || '5. **Actividades culturales**: Actividades o experiencias culturales participativas.' || CHAR(10) || '6. **Notas**: Salud y seguridad, equipaje, costumbres locales, etc.' || CHAR(10) || '7. **Presupuesto**: Desglose de costos de transporte, alojamiento, comidas, entradas, etc.' || CHAR(10) || '' || CHAR(10) || 'Formato de salida: Usar Markdown, estructura clara, con títulos y listas.' || CHAR(10) || 'Si la información es insuficiente, se pueden hacer preguntas aclaratorias razonables.',1790249339723);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (24,130,'ncv71q80l6h78k41h4zskcal',0,'Generador de mensajes de bendición','Haz que cada bendición sea única. Personaliza mensajes de bendición según sus necesidades y tono emocional.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"customType": "", "greetingType": "", "otherDetails": "", "relationship": "", "greetingStyle": "", "customRelation": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["section_relation", "section_type", "section_style", "section_details", "submit"], "component": "Column"}, {"id": "section_relation", "spacing": 8, "children": ["label_relation", "input_relation"], "component": "Column"}, {"id": "label_relation", "text": "Relación con el destinatario", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_relation", "value": {"path": "/relationship"}, "options": [{"label": "Hermano mayor", "value": "Hermano mayor"}, {"label": "Hermano menor", "value": "Hermano menor"}, {"label": "Hermana mayor", "value": "Hermana mayor"}, {"label": "Hermana menor", "value": "Hermana menor"}, {"label": "Cliente", "value": "Cliente"}, {"label": "Colega", "value": "Colega"}, {"label": "Líder", "value": "Líder"}, {"label": "Profesor", "value": "Profesor"}, {"label": "Amigo", "value": "Amigo"}, {"label": "Compañero de clase", "value": "Compañero de clase"}, {"label": "Amante", "value": "Amante"}, {"kind": "custom", "label": "Otro", "value": "Otro"}], "spacing": 10, "children": ["input_custom_relation"], "component": "RowSelector"}, {"id": "input_custom_relation", "label": "Indica la relación", "value": {"path": "/customRelation"}, "component": "TextField"}, {"id": "section_type", "spacing": 8, "children": ["label_type", "input_type"], "component": "Column"}, {"id": "label_type", "text": "Tipo de felicitación", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_type", "value": {"path": "/greetingType"}, "options": [{"label": "Cumpleaños", "value": "Cumpleaños"}, {"label": "Año Nuevo", "value": "Año Nuevo"}, {"label": "Festival de Primavera", "value": "Festival de Primavera"}, {"label": "Festival del Medio Otoño", "value": "Festival del Medio Otoño"}, {"label": "Festival del Bote del Dragón", "value": "Festival del Bote del Dragón"}, {"label": "Festival de los Faroles", "value": "Festival de los Faroles"}, {"label": "Día de San Valentín", "value": "Día de San Valentín"}, {"label": "Día de San Valentín", "value": "Día de San Valentín"}, {"label": "Día de la Madre", "value": "Día de la Madre"}, {"label": "Día del Padre", "value": "Día del Padre"}, {"label": "Día del Maestro", "value": "Día del Maestro"}, {"label": "Día del Niño", "value": "Día del Niño"}, {"label": "Navidad", "value": "Navidad"}, {"label": "Boda", "value": "Boda"}, {"label": "Avance académico", "value": "Avance académico"}, {"label": "Graduación", "value": "Graduación"}, {"label": "Búsqueda de empleo", "value": "Búsqueda de empleo"}, {"label": "Mudanza", "value": "Mudanza"}, {"kind": "custom", "label": "Otro", "value": "Otro"}], "spacing": 10, "children": ["input_custom_type"], "component": "RowSelector"}, {"id": "input_custom_type", "label": "Indica el tipo de felicitación", "value": {"path": "/customType"}, "component": "TextField"}, {"id": "section_style", "spacing": 8, "children": ["label_style", "input_style"], "component": "Column"}, {"id": "label_style", "text": "Estilo de felicitación", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_style", "value": {"path": "/greetingStyle"}, "options": ["Conmovedor", "Humor divertido", "Formal y solemne", "Artístico y poético", "Conciso y elegante", "Estilo antiguo", "Juguetón y adorable", "Apasionado"], "spacing": 10, "component": "RowSelector", "maxSelected": 1}, {"id": "section_details", "spacing": 8, "children": ["label_details", "input_details"], "component": "Column"}, {"id": "label_details", "text": "Otras notas", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_details", "label": "Nota adicional (opcional)", "value": {"path": "/otherDetails"}, "component": "TextField", "supportingText": "Por ejemplo: desea incluir palabras específicas, combinar con cierto evento, etc."}, {"id": "submit", "label": "Generar mensaje de felicitación", "action": {"event": {"name": "submit", "context": {"prompt": "Tipo de saludo: ${greetingType} ${customType}\nRelación con el destinatario: ${relationship} ${customRelation}\nEstilo del saludo: ${greetingStyle}\nNotas adicionales: ${otherDetails}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Eres un experto en generar mensajes de felicitación cálidos y creativos. Genera mensajes personalizados según la información proporcionada por el usuario.' || CHAR(10) || 'Eres un experto en generar mensajes de felicitación cálidos y creativos. Genera mensajes personalizados según la información proporcionada por el usuario.' || CHAR(10) || '' || CHAR(10) || '**Flujo de trabajo:**' || CHAR(10) || '1. Analizar la relación, el tipo de felicitación, las preferencias de estilo, etc., ingresados por el usuario.' || CHAR(10) || '2. Determinar el tono según la relación (familiar cercano, amigo relajado, líder formal, etc.).' || CHAR(10) || '3. Incorporar elementos culturales y ambiente festivo según el tipo de felicitación.' || CHAR(10) || '4. Ajustar la expresión según el estilo de felicitación elegido (humorístico, poético, clásico, etc.).' || CHAR(10) || '5. Si hay una relación o tipo personalizado, priorizar el contenido personalizado.' || CHAR(10) || '6. Si hay notas adicionales, integrarlas en el mensaje.' || CHAR(10) || '' || CHAR(10) || '**Requisitos de salida:**' || CHAR(10) || '- Generar 1-3 mensajes de felicitación de diferentes estilos' || CHAR(10) || '- Los mensajes deben ser cálidos, sinceros y creativos' || CHAR(10) || '- Deben ajustarse al significado cultural de la festividad/ocasión correspondiente' || CHAR(10) || '- Longitud entre 50 y 150 caracteres' || CHAR(10) || '- Usar formato Markdown, cada mensaje en un párrafo separado',1790249339721);
